ize	equ $7E	Text Size	 [Integer]otxFace	equ $80	Text Face	 [TextStyle]otxMode	equ $82	Text Mode	 [Integer]ospExtra	equ $84	Fixed Point Value	 [Fixed]ochExtra	equ $88	Fixed Point Value	 [Fixed]ofgColor	equ $8C	ForeGround Color	 [Integer]obgColor	equ $8E	BackGround Color	 [Integer]opicSave	equ $90	PicSave	 [Handle]orgnSave	equ $94	RgnSave	 [Handle]opolySave	equ $98	PolySave	 [Handle]ografProcs	equ $9C	GrafProcs	 [ProcPtr]oarcRot	equ $A0	ArcRot	 [Integer]ouserField	equ $A2	UserField	 [Longint]osysField	equ $A6	SysField	 [Longint];; --- LocInfo record offsets ---------------------------------------------;oportSCB	equ 0	SCB bitfieldoptrToPixImage	equ 2	ImageRefolWidth	equ 6	WidthoboundsRect	equ 8	BoundsRect;; --- Font information record -------------------------------------------;ascent	equ 0descent	equ ascent+2widMax	equ descent+2leading	equ widMax+2;; --- Window record	offsets  ----------------------------------------------;owNext	equ $00	Pointer to next window Record.       [GrafPortPtr]oport	equ $04	Window's port.                       [GrafPort]owPadding	equ $AE	Space for possible future expansion  [GrafPort]owStrucRgn	equ $BE	Region of frame plus content.        [RgnHandle]owContRgn	equ $C2	Content region.	                 [RgnHandle]owUpdateRgn	equ $C6	Update region.	                 [RgnHandle]owControls	equ $CA	Window's control list.               [CtlRecHndl]owFrameCtrls	equ $CE	Window frame's control list.         [CtlRecHndl]owFrame	equ $D2	Bit flags.	                 [WindowFrame];; --- Window coordinate offsets ------------------------------------------------;TITLEH	equ 13	;Height of title bar.TITLEL	equ 2	;Space on left and right of title bar pattern.TITLET	equ 3	;Space on top and bottom of title bar pattern.;CLOSEL	equ 10	;Left side of window to left side of close box.CLOSET	equ 2	;Top of window to top of close box.CLOSEW	equ 22	;Width of close box.CLOSEH	equ 11	;Height of close box.;; --- Flag masks for wkind ------------------------------;W_SYSTEM	equ $8000	1 = system window.;; --- Window Frame Type Masks ----------------------;F_TITLE	equ $8000	TRUE = title bar.F_CLOSE	equ $4000	TRUE = close box.F_RSCRL	equ $1000	TRUE = right scroll	bar.F_BSCRL	equ $0800	TRUE = bottom scroll bar.F_SIZE	equ $0400	TRUE = sizer box.F_ZOOM	equ $0100	TRUE = full box.F_MOVTIT	equ $0080	TRUE = allow move on title bar.F_VIS	equ $0020	TRUE = window is visible.F_INFO	equ $0010	TRUE = content inset from left side.F_Ctl_TIE	equ $0008	FALSE= control state tied to window'sF_ALLOCATE	equ $0004	TRUE = window record allocated by me.F_FULL	equ $0002	TRUE = window is full.F_HIGHLT	equ $0001	TRUE = frame is highlighted.;; --- Window color table offsets -----------------------------;FRAME_CLR	equ 0	Frame's outline.TITLE_CLR	equ FRAME_CLR+2	Title's color.BAR_CLR	equ TITLE_CLR+2	Title bar's initerior.GROW_CLR	equ BAR_CLR+2	Grow box interior.INFOR_CLR	equ GROW_CLR+2	Information bar interior.COLORSIZ	equ INFOR_CLR+2	Size of color table.;; --- Variation code, command to window	definition procedure ----------;wDraw	equ 0	Draw window's frame.wHit	equ 1	Tell what region given point is in.wCalcRgns	equ 2	Calculate wstrucRgn	and wcontRgn.wNew	equ 3	Do any additional initialization.wDispose	equ 4	Take any additional	disposal actions.wGrow	equ 5	Draw window's grow image.;; --- Hit return flags -------------------------------------------------;Null	equ 0wInDesk	equ $10	On Desktop.wInMenuBar	equ $11	On System Menu Bar.wInSysWindow	equ $12	On System window.winContent	equ $13	In content region.wInDrag	equ $14	In drag region.wInGrow	equ $15	In grow region, active window only.wInGoAway	equ $16	In go-away region, active window only.wInZoom	equ $17	In zoom region, active window only.wInInfo	equ $18	In information bar.wInVScroll	equ $19	In right scroll bar.wInHScroll	equ $1A	In bottom scroll bar.wInFrame	equ $1B	In frame, but not on anything else.;; --- Color and pattern equates ---------------------------------------------;BLACK	equ $0000RED	equ $1111GREEN	equ $2222WHITE	equ $ffffP_SOLID	equ $0000P_DITHER	equ $0100P_DOTTED	equ $0200P_LINED	equ $0300;; --- Control record offsets ---------------------------------------------;	DSect 0CtlNext	LONGCtlOwner	LONGCtlRect	block 8CtlFlag	byteCtlHilite	byteCtlValue	WORDCtlProc	LONGCtlAction	LONGCtlData	LONGCtlrefCon	LONGCtlColor	LONGThumb	BLOCK 8PageRegion	BLOCK 8NormalCtlSize	equ CtlColor+4;; --- Simple button	color table offsets	-------------------------------------;simpOutline	equ 0simpNorBack	equ 2simpSelBack	equ 4simpNorText	equ 6simpSelText	equ 8;; --- Scroll bar color table offsets -------------------------------------;scrollOutline	equ 0ArrowNorColor	equ 2ArrowSelColor	equ 4ArrowBackColor	equ 6ThumbNorColor	equ 8PageRgnColor	equ 12InactiveColor	equ 14;; --- General CtlFlag bit flags ---------------------------------------------;C_HILITE	equ $00FF	Hilited part, 255 =	inactive.CTL_INVIS	equ $0080	1 if control is invisible.;; --- CtlFlag bits for scroll bars -----------------------------------------;UP_FLAG	equ $0001	Up arrow.DOWN_FLAG	equ $0002	Down arrow.LEFT_FLAG	equ $0004	Left arrow.RIGHT_FLAG	equ $0008	Right arrow.DIR_SCROLL	equ $0010	0 = vertical, 1 = horizontal scroll.;; --- CtlFlag bits for simple buttons --------------------------------------;SB_BOLD	equ $0001;; --- Commands passed to control definition procedures ---------------------;drawCntl	equ 0	0 Draw the control.calcCRect	equ drawCntl+1	1 Compute the drag RECT.testCntl	equ calcCRect+1	2 Perform a hit test on the control.initCntl	equ testCntl+1	3 Perform additional initialization.dispCntl	equ initCntl+1	4 Perform additional disposal.posCntl	equ dispCntl+1	5 Called when dragging complete with delta.thumbCntl	equ posCntl+1	6 Setup for dragging.dragCntl	equ thumbCntl+1	7 Perform dragging.autoTrack	equ dragCntl+1	8 Called while dragging.newValue	equ autoTrack+1	9 Called when new value is set.setParams	equ newValue+1	10 Called when min and max are set.moveCntl	equ setParams+1	11 Move entire control.recSize	equ moveCntl+1	12 Return size of control's record.;; --- Part codes for standard controls -----------------;BUTT_PART	equ 2CHECK_PART	equ 3RADIO_PART	equ 4UP_PART	equ 5DOWN_PART	equ 6UPP_PART	equ 7DOWNP_PART	equ 8GROW_PART	equ 10THUMB_PART	equ 129;; --- Control Manager tool number -----------------------------------------;CtlToolNum	equ 16;; --- Control Manager error codes -----------------------------------------;OFF_ERR	equ $1002	Control Manager not	initialized.NOT_IN_LIST	equ $1003	Control not in window list.;; --- Control icon numbers -------------------------------;UP_ARROW	equ 8DOWN_ARROW	equ 10LEFT_ARROW	equ 12RITE_ARROW	equ 14GROW_ICON	equ 16TITLE_SPACE	equ 4	Number of pixels added to the width of;	                   	a check box or radio button to get the;	                   	starting X position of the title.; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;                RAM area offsets.; = = = = = = = = =	= = = = = = = = = =	= = = = = = =pattern	equ 0	32 Pattern buffer.myevent	equ pattern+32	16 Event record.fontHandle	equ myevent+16	6 Fake handle for fonts.MyID	equ fontHandle+6	2 Memory Manager ID	number.MyDPage	equ MyID+2	2 Direct page passed to StartUp.visRect	equ MyDPage+2	8 Current window's visible RECT.eraseFlag	equ visRect+8	2 Flag for HidControl and EraseControl.Ctl_font	equ eraseFlag+2	4 Handle of icon font.vert_pen	equ ctl_font+4	2 Width of vertical	lines.GraphicsMode	equ vert_pen+2	2 $0000 = 320 mode,	$0080 = 640 mode.min_thumb	equ GraphicsMode+2	2 Minimum horizontal thumb size.active	equ min_thumb+2	2 FALSE = enabled, TRUE = dimmed.state	equ active+2	2 0=normal, 1=whole, 2=selected.uArrowH	equ state+2	2 Height of up arrow icon.uArrowW	equ uArrowH+2	2 Width of up arrow	icon.dArrowH	equ uArrowW+2	2 Height of down arrow icon.dArrowW	equ dArrowH+2	2 Width of down arrow icon.lArrowH	equ dArrowW+2	2 Height of left arrow icon.lArrowW	equ lArrowH+2	2 Width of left arrow icon.rArrowH	equ lArrowW+2	2 Height of right arrow icon.rArrowW	equ rArrowH+2	2 Width of right arrow icon.limit_blk	equ rArrowW+2	Parameter block for	calling DragControl.action_proc	equ limit_blk+0	Action procedure to	call, zero = none.bound_rect	equ action_proc+4	Limit RECT.slop_rect	equ bound_rect+8	Slop RECT.axis_param	equ slop_rect+8	Axis.drag_patt	equ axis_param+2	Pointer to drag pattern.drag_rect	equ drag_patt+4	RECT to drag.fontInfo	equ drag_rect+8	8 Font information record.;-----------------------------------------------------------;; Variables needed by NewControl2;SavedRescID	equ fontInfo+8	SavedHandle	equ SavedRescID+4	ErrorCode	equ SavedHandle+4ParamTextPtr	equ ErrorCode+2RAMSIZE	equ ParamTextPtr+4	Number of bytes in RAM area.;-----------------------------------------------------------;; Toolbox Patcher equates;oCMDispatcher	equ $0000